def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2))
            if square <= cells:
                pieces.append((square, 1, 0, r, c))

            for missing, color in [
                ((0, 0), 2),
                ((0, 1), 4),
                ((1, 0), 3),
                ((1, 1), 5),
            ]:
                tri = frozenset(
                    (r + dr, c + dc)
                    for dr in range(2)
                    for dc in range(2)
                    if (dr, dc) != missing
                )
                if tri <= cells:
                    pieces.append((tri, color, 1, r, c))

    pieces.sort(key=lambda p: (p[2], p[3], p[4], p[1]))

    def search(remaining, chosen):
        if not remaining:
            return chosen
        cell = min(remaining)
        for shape, color, _, _, _ in pieces:
            if cell in shape and shape <= remaining:
                result = search(remaining - shape, chosen + [(shape, color)])
                if result is not None:
                    return result
        return None

    tiling = search(cells, [])
    out = [[0] * w for _ in range(h)]
    if tiling is not None:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
